              let selected = item.currentMediaSelection.selectedMediaOption(in: group) else { return nil }
        return choices.first { $0.option == selected }?.id ?? unlistedSelectionID
    }
    var unlistedSelectionID: String { "\(generation):current" }
    var unlistedSelectionName: String? {
