            let index = predicate.searchDirection == .next
                ? current.map { $0 + 1 } ?? 0
                : current.map { $0 - 1 } ?? self.matches.count - 1
            guard self.matches.indices.contains(index) else { return nil }
            let match = self.matches[index]
